+func mergeLibraryVuln(existing, incoming models.VulnInfo) models.VulnInfo {
+	existing.LibraryFixedIns = append(existing.LibraryFixedIns, incoming.LibraryFixedIns...)
+	existing.Confidences.AppendIfMissing(models.TrivyMatch)
+	if existing.CveContents == nil {
+		existing.CveContents = incoming.CveContents
+	} else {
+		for source, content := range incoming.CveContents {
+			existing.CveContents[source] = content
+		}
+	}
+	return existing
