+package libmanager
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+func TestMergeLibraryVulnKeepsBothLockfiles(t *testing.T) {
+	existing := models.VulnInfo{
+		CveID:           "CVE-1",
+		LibraryFixedIns: models.LibraryFixedIns{{Path: "/one/Pipfile.lock", Name: "requests", FixedIn: "1.1"}},
+	}
+	incoming := models.VulnInfo{
+		CveID:           "CVE-1",
+		LibraryFixedIns: models.LibraryFixedIns{{Path: "/two/Pipfile.lock", Name: "requests", FixedIn: "2.1"}},
+	}
+	got := mergeLibraryVuln(existing, incoming)
+	if len(got.LibraryFixedIns) != 2 || got.LibraryFixedIns[0].Path != "/one/Pipfile.lock" || got.LibraryFixedIns[1].Path != "/two/Pipfile.lock" {
+		t.Fatalf("merged lockfiles: %#v", got.LibraryFixedIns)
+	}
+}
