@@ -0,0 +1,31 @@
+package scan
+
+import (
+	"fmt"
+	"testing"
+
+	"github.com/aquasecurity/fanal/analyzer"
+	"github.com/future-architect/vuls/models"
+)
+
+func TestConvertLibWithScannerKeepsLockfilePaths(t *testing.T) {
+	var scanners models.LibraryScanners
+	for _, tc := range []struct{ path, version string }{
+		{"/app/one/Pipfile.lock", "1.0.0"},
+		{"/app/two/Pipfile.lock", "2.0.0"},
+	} {
+		content := []byte(fmt.Sprintf(`{"default":{"requests":{"version":"==%s"}}}`, tc.version))
+		result, err := analyzer.AnalyzeFile(tc.path, &DummyFileInfo{}, func() ([]byte, error) { return content, nil })
+		if err != nil {
+			t.Fatal(err)
+		}
+		scanners = append(scanners, convertLibWithScanner(result)...)
+		found := scanners.Find(tc.path, "requests")
+		if got := found[tc.path].Version; got != tc.version {
+			t.Fatalf("%s: got version %q, want %q", tc.path, got, tc.version)
+		}
+	}
+	if len(scanners) != 2 {
+		t.Fatalf("got %d scanners, want 2", len(scanners))
+	}
+}
